#include <algorithm>
#include <functional>
#include <vector>

std::vector<int> topScores(std::vector<int> scores, std::size_t count)
{
    std::sort(scores.begin(), scores.end(), std::greater{});
    if (scores.size() > count)
    {
        scores.resize(count);
    }
    return scores;
}

int rankOf(const std::vector<int>& scores, int score)
{
    const auto higher{ std::count_if(scores.begin(), scores.end(), [score](int s) { return s > score; }) };
    return static_cast<int>(higher) + 1;
}

unitTests:
TEST("top three") { CHECK_EQ(topScores({ 40, 95, 70, 88, 12 }, 3), (std::vector<int>{ 95, 88, 70 })); }
TEST("asking for more than there are") { CHECK_EQ(topScores({ 3, 9 }, 5), (std::vector<int>{ 9, 3 })); }
TEST("top zero") { CHECK(topScores({ 1, 2, 3 }, 0).empty()); }
TEST("rankOf") { const std::vector<int> s{ 40, 95, 70, 88, 12 }; CHECK_EQ(rankOf(s, 95), 1); CHECK_EQ(rankOf(s, 70), 3); CHECK_EQ(rankOf(s, 12), 5); CHECK_EQ(rankOf(s, 100), 1); CHECK_EQ(rankOf(s, 0), 6); }
TEST("equal scores share a rank") { CHECK_EQ(rankOf({ 50, 50, 40 }, 50), 1); CHECK_EQ(rankOf({ 50, 50, 40 }, 40), 3); }

